def min_flips(a, b, c):
    total = 0
    for i in range(32):
        bit_a = (a >> i) & 1
        bit_b = (b >> i) & 1
        bit_c = (c >> i) & 1
        if bit_c == 0:
            total += bit_a + bit_b                                  # flip off every 1 bit present here
        else:
            if bit_a == 0 and bit_b == 0:
                total += 1                                             # need exactly one flip to turn a bit on
    return total


if __name__ == "__main__":
    print(min_flips(2, 6, 5))

