import java.util.*;

public class Main {
    int minFlips(int a, int b, int c) {
        int total = 0;
        for (int i = 0; i < 32; i++) {
            int bitA = (a >> i) & 1;
            int bitB = (b >> i) & 1;
            int bitC = (c >> i) & 1;
            if (bitC == 0) {
                total += bitA + bitB;                                       // flip off every 1 bit present here
            } else {
                if (bitA == 0 && bitB == 0) total += 1;                        // need exactly one flip to turn a bit on
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minFlips(2, 6, 5));
    }
}

