import java.util.*;

public class Main {
    int minFlips(int a, int b, int c) {
        int turnOffA = Integer.bitCount(a & ~c);                     // bits of a that must be turned off
        int turnOffB = Integer.bitCount(b & ~c);                       // bits of b that must be turned off
        int turnOn = Integer.bitCount(c & ~a & ~b);                      // bits where neither a nor b has a 1, but c needs one
        return turnOffA + turnOffB + turnOn;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minFlips(2, 6, 5));
    }
}

